      this.requests.forEach(r => r.reject(Error('Workspace worker stopped; reload to reconnect'))); this.requests.clear();
      worker.terminate(); this.worker = undefined;
    };
    worker.onerror = fail; worker.onmessageerror = fail;
    return worker;
  }
  private request<T>(input: Record<string, unknown>): Promise<T> {
    return new Promise((resolve, reject) => {
      const id = ++this.id;
      this.requests.set(id, { resolve: value => resolve(value as T), reject });
      try { this.ensureWorker().postMessage({ ...input, id, endpoint: new URL(this.endpoint, location.href).href }); }
      catch (e) { this.requests.delete(id); reject(e); }
    });
  }
  load() {
    return this.ready ??= this.request<{ state: WorkspaceRecordState; workspace: MappingWorkspaceSnapshot | null }>({ type: 'load' }).then(({ state, workspace }) => {
      this.records = new RecordStorage(state, { write: batch => this.request({ type: 'write', batch }) }); return workspace;
    }).catch(error => { this.ready = undefined; throw error; });
  }
  async project(snapshot: MappingWorkspaceSnapshot) { return this.request<StorageChange[]>({ type: 'project', snapshot }); }
  async save(snapshot: MappingWorkspaceSnapshot) {
    await this.load(); await this.records!.flush();
    const changes = await this.project(snapshot);
    await this.records!.commit(changes);
  }

  /** Publish one canvas atomically without exporting/revalidating unrelated histories. */
  async saveDocument(document: MappingDocumentSnapshot, index: WorkspaceIndex, create = false) {
    await this.load(); await this.records!.flush();
    if (create && this.records!.get(documentPrefix(document.representationId) + 'metadata')) throw Error('Canvas already exists');
    await this.records!.commit([
      ...Object.entries(documentRecords(document)).map(([key, value]) => ({ key, value })),
      { key: 'workspace', value: index }
    ]);
  }

  async restore() {
    await this.records?.flush();
    this.records?.dispose(); this.ready = undefined;
    return this.load();
  }
  async flush() { await this.load(); await this.records!.flush(); }
  dispose() {
    this.records?.dispose(); this.worker?.terminate(); this.worker = undefined;
    this.requests.forEach(r => r.reject(Error('Storage closed'))); this.requests.clear();
  }
}

import { NativeSelectionOwnership } from '../../../../domain/mapping/selection/selectionGesture';
import { type Editor, type TLShapePartial } from 'tldraw';
import { flattenGrid, resolveScene } from '../../../../domain/core/diagrams/lineGrid';
import { selectedDiagramIds } from '../../../../domain/mapping/selection/selectionState';
import { updateDisplayGeometry } from '../../../../domain/mapping/workspace/displayModel';
import type { MappingDocumentController, DiagramOperation } from '../../../../domain/mapping/workspace/mappingDocumentController';
import { DEFAULT_CELL, mappingShapeId, projectMappingShapes } from './shapeProjection';
import type { MappingShape } from './MappingShapeUtil';

/** The Editor owns live geometry and undo. The domain controller supplies semantic
 * commands and an immutable checkpoint archive for persistence/headless proposals.
 * No controller writes occur on camera or pointer-move frames. */
export class MappingEditorRuntime {
  private disposed = false;
  private syncing = false;
  private settling = false;
  private navigating = false;
  private dirty = false;
  private pendingProjection = false;
  private checkpoint = '';
  private unsubscribes: (() => void)[] = [];
  private projected = new Map<string, TLShapePartial<MappingShape>>();
  constructor(readonly editor: Editor, readonly controller: MappingDocumentController, readonly selectionOwnership = new NativeSelectionOwnership()) {
    this.hydrate();
    this.unsubscribes.push(controller.attachEditorDriver({ settle: () => { if (!this.settling) { this.editor.complete(); this.settle(true, false); } }, undo: redo => this.undo(redo) }));
    let previous = controller.getSnapshot();
    this.unsubscribes.push(controller.subscribe(() => {
      const next = controller.getSnapshot();
      if (next.canvas.selection !== previous.canvas.selection && !this.settling && !this.navigating)
        this.selectionOwnership.claim('application');
      const relevant = next.canvasRevisionId !== previous.canvasRevisionId || next.document !== previous.document
        || next.canvas.display !== previous.canvas.display || next.canvas.diagramViews !== previous.canvas.diagramViews
        || next.canvas.selection !== previous.canvas.selection || next.cell !== previous.cell;
      previous = next;
      if (relevant) this.publish();
    }));
    // This synchronous observer distinguishes history navigation from an ordinary
    // shape edit before another API request can observe the old checkpoint.
    this.unsubscribes.push(editor.sideEffects.registerAfterChangeHandler('document', (_before, after) => {
      const id = after.meta.mappingCheckpoint;
      if (this.syncing || typeof id !== 'string' || id === controller.getSnapshot().canvasRevisionId) return;
      this.navigating = true;
      try { controller.restoreEditorCheckpoint(id); this.checkpoint = id; this.publish(false); }
      finally { this.navigating = false; }
    }));
    this.unsubscribes.push(editor.store.listen(({ changes }) => {
      if (this.syncing) return;
      if (Object.values(changes.added).some(record => record.typeName === 'shape')
        || Object.values(changes.removed).some(record => record.typeName === 'shape')
        || Object.values(changes.updated).some(([before, after]) => after.typeName === 'shape'
          || after.typeName === 'instance_page_state' && before.typeName === 'instance_page_state'
            && after.selectedShapeIds.join() !== before.selectedShapeIds.join())) this.dirty = true;
    }, { scope: 'all' }));
    const tick = () => {
      if (editor.inputs.getIsPointing() || editor.inputs.getIsDragging() || editor.inputs.getIsPinching()) return;
      // Finish native geometry first, but never overwrite a pending domain selection.
      if (this.dirty) this.settle(false, !this.pendingProjection && this.selectionOwnership.captureSelection);
      if (this.pendingProjection) this.publish();
    };
    editor.on('tick', tick);
    this.unsubscribes.push(() => { editor.off('tick', tick); });
  }
  private setCheckpoint(id: string) {
    const document = this.editor.getDocumentSettings();
    // updateDocumentSettings intentionally ignores history in the SDK. This
    // application checkpoint is document data and must share the shape diff.
    this.editor.store.put([{ ...document, meta: { ...document.meta, mappingCheckpoint: id } }]);
  }
  /** Replay only checkpoint references. Old shape geometry is materialized lazily
   * on navigation, so startup does not reparse every historical ASCII document. */
  private hydrate() {
    this.syncing = true;
    try {
      const record = this.controller.editorHistory();
      const sequence = [...record.past, record.headId, ...[...record.future].reverse()];
      this.editor.run(() => this.setCheckpoint(sequence[0]), { history: 'ignore' });
      this.editor.clearHistory();
      for (const id of sequence.slice(1)) {
        this.editor.markHistoryStoppingPoint('mapping checkpoint');
        this.setCheckpoint(id);
      }
      for (let i = 0; i < record.future.length; i++) this.editor.undo();
      this.checkpoint = record.headId;
      this.writeShapes(false);
    } finally { this.syncing = false; }
  }
  private writeShapes(record: boolean) {
    const shapes = projectMappingShapes(this.controller.getSnapshot()).map(shape => ({ ...shape, parentId: shape.parentId ?? this.editor.getCurrentPageId() }));
    const ids = new Set(shapes.map(shape => shape.id));
    this.editor.run(() => {
      const removed = this.editor.getCurrentPageShapes().filter(shape => shape.type === 'mapping-box' && !ids.has(shape.id));
      this.editor.deleteShapes(removed.map(shape => shape.id));
      const create: TLShapePartial<MappingShape>[] = [], update: TLShapePartial<MappingShape>[] = [];
      for (const shape of shapes) {
        const current = this.editor.getShape<MappingShape>(shape.id);
        if (!current) create.push(shape);
        else if (current.parentId !== (shape.parentId ?? this.editor.getCurrentPageId()) || current.x !== shape.x || current.y !== shape.y || current.isLocked !== shape.isLocked
          || JSON.stringify(current.props) !== JSON.stringify(shape.props)) update.push(shape);
      }
      if (create.length) this.editor.createShapes(create);
      if (update.length) this.editor.updateShapes(update);
      // Edges stay above diagram shapes, including after creation and history replay.
      const edgeIds = shapes.filter(shape => shape.props?.kind === 'arrow').map(shape => shape.id);
      this.editor.run(() => this.editor.bringToFront([...edgeIds, ...this.editor.getCurrentPageShapes().filter(shape => shape.type === 'mapping-box' && (shape as MappingShape).props.kind === 'diagram-side-panel').map(shape => shape.id)]), { ignoreShapeLock: true });
      this.projected = new Map(shapes.map(shape => [shape.props!.nodeId!, shape]));
      const selected = this.selectedShapeIds();
      const native = this.editor.getSelectedShapeIds();
      if (native.length !== selected.length || selected.some(id => !native.includes(id))) this.editor.setSelectedShapes(selected);
    }, { history: record ? 'record' : 'ignore' });
  }
  private selectedShapeIds() {
    this.selectionOwnership.dragDiagramIds = this.selectionOwnership.dragDiagramIds.filter(id => this.editor.getShape(mappingShapeId(id)));
    return [...new Set([...selectedDiagramIds(this.controller.getSnapshot().canvas.selection), ...this.selectionOwnership.dragDiagramIds])]
      .map(mappingShapeId).filter(id => this.editor.getShape(id));
  }
  private publish(record = true) {
    if (this.syncing || this.disposed) return;
    this.syncing = true;
    try {
      const id = this.controller.getSnapshot().canvasRevisionId;
      const changed = id !== this.checkpoint;
      if (!changed && this.editor.inputs.getIsPointing()) { this.pendingProjection = true; return; }
      this.pendingProjection = false;
      if (changed && record && !this.settling && !this.navigating) this.editor.markHistoryStoppingPoint('mapping command');
      this.editor.run(() => {
        this.writeShapes(changed && record && !this.navigating);
        this.setCheckpoint(id);
      }, { history: changed && record && !this.navigating ? 'record' : 'ignore' });
      this.checkpoint = id;
    } finally { this.syncing = false; }
  }
  settle(force = false, captureSelection = this.selectionOwnership.captureSelection) {
    if (this.syncing || this.settling || this.navigating || this.disposed) return;
    if (!force && this.editor.inputs.getIsPointing()) return;
    this.dirty = false;
    this.settling = true;
    try {
      let selected = this.editor.getSelectedShapes().filter(shape => shape.type === 'mapping-box' && shape.props.kind === 'diagram')
        .map(shape => (shape as MappingShape).props.nodeId);
      const snapshot = this.controller.getSnapshot();
      const cell = snapshot.cell?.width ? snapshot.cell : DEFAULT_CELL;
      const boxes = flattenGrid(resolveScene(snapshot.document.scene));
      const nativeShapes = this.editor.getCurrentPageShapes();
      const clones = nativeShapes.filter(shape => shape.type === 'mapping-box' && shape.id !== mappingShapeId(shape.props.nodeId));
      const unsupportedClone = clones.some(shape => shape.type === 'mapping-box' && (shape.props.kind !== 'diagram'
        || !boxes.some(box => box.children.some(child => `grid:${child.box.id}` === shape.props.nodeId))));
      if (unsupportedClone) { this.editor.deleteShapes(clones.map(shape => shape.id)); selected = []; }
      const moves: DiagramOperation[] = [];
      let display = snapshot.canvas.display;
      for (const shape of this.editor.getCurrentPageShapes()) {
        if (shape.type !== 'mapping-box') continue;
        const previous = this.projected.get(shape.props.nodeId);
        if (!previous) continue;
        if (shape.id !== mappingShapeId(shape.props.nodeId)) {
          if (shape.props.kind === 'diagram') {
            const id = `copy-${crypto.randomUUID()}`, point = this.editor.getShapePageBounds(shape)!;
            moves.push({ method: 'duplicate-instance', sourceNodeId: shape.props.nodeId, id,
              position: { column: Math.max(0, Math.round(point.x / cell.width)), row: Math.max(0, Math.round(point.y / cell.height)) } });
            if (this.editor.getSelectedShapeIds().includes(shape.id)) selected = selected.map(nodeId => nodeId === shape.props.nodeId ? `grid:${id}` : nodeId);
          } else {
            // Pane and group copies need semantic ownership remapping. Until such
            // a command exists, cancel these temporary native clones.
            this.editor.deleteShapes([shape.id]);
          }
          continue;
        }
        if (shape.props.nodeId.startsWith('grid:')) {
          if (shape.x === previous.x && shape.y === previous.y) continue;
          const id = shape.props.nodeId.slice(5), parent = boxes.find(box => box.children.some(child => child.box.id === id));
          if (!parent && shape.props.kind !== 'diagram') continue;
          const point = this.editor.getShapePageBounds(shape)!;
          moves.push({ method: 'move', nodeId: shape.props.nodeId, position: {
            column: Math.max(0, Math.round(point.x / cell.width)),
            row: Math.max(0, Math.round(point.y / cell.height)) } });
        } else {
          const node = display.nodes[shape.props.nodeId.slice(9)];
          if (!node) continue;
          if (shape.x === previous.x && shape.y === previous.y && shape.props.w === previous.props?.w && shape.props.h === previous.props?.h) continue;
          display = updateDisplayGeometry(display, node.id, { position: { x: shape.x, y: shape.y }, bounds: { width: shape.props.w, height: shape.props.h } });
          display = { ...display, nodes: { ...display.nodes, [node.id]: { ...display.nodes[node.id],
            geometryPolicy: { placement: 'manual', sizing: shape.props.w !== previous.props?.w || shape.props.h !== previous.props?.h ? 'fixed' : node.geometryPolicy.sizing },
            ...(node.kind === 'conversation' && node.expansion === 'collapsed' ? { canvasAnchor: { x: shape.x, y: shape.y } } : {}) } } };
        }
      }
      const canvas = display === snapshot.canvas.display ? snapshot.canvas : { ...snapshot.canvas, display };
      // Native selection only enables dragging. Content membership changes through
      // explicit application gestures (node selection, marquee, whole-diagram double-click).
      if (captureSelection) this.selectionOwnership.dragDiagramIds = selected.filter(id => !selectedDiagramIds(canvas.selection).includes(id));
      if (moves.length || canvas !== snapshot.canvas) this.controller.commitEditorGesture(moves, canvas);
      if (!captureSelection) {
        const ids = this.selectedShapeIds();
        this.editor.run(() => this.editor.setSelectedShapes(ids), { history: 'ignore' });
      }
    } finally { this.settling = false; }
  }
  undo(redo = false) {
    this.editor.complete(); this.settle();
    const history = this.controller.editorHistory();
    if ((redo ? history.redoTransactionId : history.undoTransactionId))
      throw new Error('Use workspace undo/redo for a canvas transfer.');
    if (redo) this.editor.redo(); else this.editor.undo();
  }
  dispose() {
    this.editor.complete(); this.settle(); this.disposed = true;
    this.unsubscribes.splice(0).reverse().forEach(dispose => dispose());
  }
}

import { ownerScope } from '../../../domain/core/presentation/diagramAlternative';
import { generateDiagram } from '../../core/diagrams/generateDiagram';
import { createStoredDiagram, importDiagramRevision, getDiagramRevision, submitStoredDiagramEdit } from '../../../domain/core/diagrams/diagramRevisionStore';
import type { GeneratedDiagramEdit } from '../../../domain/core/diagrams/generatedDiagramEdit';
import { selectionExcerpt } from '../../../domain/mapping/workspace/selectionClipboard';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes';
import { diagramReplacementRanges } from '../../../domain/core/diagrams/diagramSubtreeEdit';
import { revisionScope, reviewRevisionIds, validateRevisionReview, type DiagramRevisionReview } from '../../../domain/core/diagrams/diagramRevisionReview';
import { validateConnectionAnchor } from '../../../domain/core/diagrams/diagramConnection';
import { AgentContext, type AgentContextSnapshot } from '../../../domain/core/agents/agentContext';
import { diagramContextSourceFingerprint, loadDiagramAgentContext, type DiagramAgentContextStore } from '../../../domain/core/diagrams/diagramAgentContext';
import { randomUUID } from 'node:crypto';
import { CanvasHistory, type CanvasHistoryRecord } from '../../../domain/core/diagrams/canvasHistory';
import type { DiagramGenerator } from '../../../domain/core/diagrams/diagramGeneration';
import type { DiagramRevisionResult, DiagramRevision } from '../../../domain/core/diagrams/diagramRevision';
import type { GridBox } from '../../../domain/core/diagrams/lineGrid';
import type { LiveDocumentSnapshot } from '../../../domain/mapping/agent/contracts';
import { editDiagramSchema } from '../../../domain/mapping/agent/diagramEdit';
import type { CreateDiagramInput, DiagramCreation, DiagramEditRun, DiagramRevisionApplication, EditDiagramInput, PromptReference } from '../../../domain/mapping/agent/diagramEdit';
import { defaultTemplateSelection, resolvePromptTemplate, type PromptOperation } from '../../../domain/mapping/agent/promptTemplates';
import { findBox } from '../../../domain/mapping/workspace/canvasDisplayNode';
import { diagramSelectionNodes } from '../../../domain/mapping/workspace/mappingDocument';

export interface DiagramEditCanvasPort {
  snapshot(sessionId: string, revisionIds?: string[]): Promise<LiveDocumentSnapshot>;
  apply(sessionId: string, input: DiagramRevisionApplication): Promise<{ version: number; unresolvedEdgeIds: string[] }>;
  /** Idempotent per requestId. Optional: runtimes without it reject create-diagram. */
  create?(sessionId: string, input: { requestId: string; expectedVersion: number; diagrams: DiagramCreation[] }): Promise<{ version: number }>;
}
interface Run {
  variants?: DiagramRevisionApplication['variants'];
  submission?: GeneratedDiagramEdit;
  agentContext?: AgentContextSnapshot;
  nextAgentContext?: AgentContextSnapshot;
  input: CreateDiagramInput;
  signature: string;
  state: DiagramEditRun;
  abort: AbortController;
  revision?: DiagramRevisionResult;
  created?: DiagramRevisionResult[];
  pending?: Promise<void>;
}
/** A reference as the model receives it: the pinned revision's text, never the live canvas. */
export type ResolvedPromptReference = { ref: number; kind: PromptReference['kind']; label: string; diagramId: string; revisionId: string }
  & ({ kind: 'diagram'; ascii: string } | { kind: 'nodes'; range: Extract<PromptReference, { kind: 'nodes' }>['range']; excerpt: string; nodes: { id: string; label: string }[] });

/** A request owns both generation and installation; retries never rerun the model. */
export class DiagramEditService {
  private runs = new Map<string, Run>();
  private requests = new Map<string, string>();
  constructor(private readonly diagrams: DiagramGenerator, private readonly canvas: DiagramEditCanvasPort,
    private readonly diagramContexts?: DiagramAgentContextStore) {}

  start(input: EditDiagramInput | CreateDiagramInput, suppliedContext?: AgentContextSnapshot, operation: PromptOperation = 'edit-diagram', submission?: GeneratedDiagramEdit): DiagramEditRun {
    if (input['presentation-alternative'] && (operation !== 'edit-diagram' || input['edit-mode'] !== 'variant')) throw Error('presentation-alternative requires edit-diagram with edit-mode variant');
    if (operation === 'edit-diagram' && 'count' in input && input.count !== undefined) throw Error('count applies only to create-diagram');
    if (operation === 'edit-diagram') input = editDiagramSchema.parse(input);
    if (input.agentContext && (input.agentContextId || suppliedContext)) throw Error('Provide only one agent context source');
    if (input.agentContext && !input.llmSessionId) throw Error('Panel context requires llmSessionId');
    const rawContext = input.agentContext ?? suppliedContext;
    const agentContext = rawContext ? AgentContext.fromSnapshot(rawContext).toSnapshot() : undefined;
    if (input.llmSessionId && agentContext && !input.agentContextId?.startsWith('saved-agent-context-') && agentContext.source.sourceSessionId !== input.llmSessionId)
      throw Error('AGENT_CONTEXT_SESSION_MISMATCH: context belongs to another panel');
    if (input.agentContextId && !agentContext) throw Error('AGENT_CONTEXT_NOT_FOUND: resolve context before starting the edit');
    if (operation !== 'edit-diagram' && !this.canvas.create) throw Error('Diagram creation UNAVAILABLE in this runtime');
    if (input.variant && operation !== 'edit-diagram') throw Error('Variants require edit-diagram');
    if (input['edit-mode'] !== undefined && operation !== 'edit-diagram') throw Error('edit-mode applies only to edit-diagram');
    if (input['edit-mode'] === 'in-place' && input.variant) throw Error('in-place mode cannot include variant options');
    if (operation !== 'edit-diagram' && (input['replace-mode'] || input.subtree || input.subtrees)) throw Error('Replacement scope applies only to edit-diagram');
    if (submission && (input.variant && input.variant.count !== 1 || 'count' in input && input.count && input.count !== 1)) throw Error('Use one batch operation per submitted diagram or variant');
    if (input.variant?.variantId && input.variant.count !== 1) throw Error('Refine one existing variant at a time');
    if (operation === 'extend-diagram' && (!input.origin || !input.sources?.length)) throw Error('Extend requires a selection and a canvas origin');
    // Fail fast on an unknown template or invalid options instead of after a model call.
    resolvePromptTemplate(input.template ?? defaultTemplateSelection(operation), operation);
    const key = JSON.stringify([input.sessionId, input.requestId]);
    const signature = JSON.stringify({ operation, input, submission, agentContextHash: agentContext?.contentHash });
    const existing = this.requests.get(key);
    if (existing) {
      const run = this.runs.get(existing)!;
      if (run.signature !== signature) throw Error('REQUEST_ID_CONFLICT: edit request differs');
      if (run.state.status === 'awaiting-acknowledgement' && !run.pending) this.launch(run, () => this.install(run));
      return structuredClone(run.state);
    }
    if (this.runs.size >= 500) throw Error('Diagram edit run capacity reached; restart the backend');
    const run: Run = { submission, agentContext, input: structuredClone(input), signature, abort: new AbortController(), state: {
      ...(input.agentContextId ? { agentContextId: input.agentContextId, agentContextHash: agentContext!.contentHash } : {}),
      runId: `diagram-edit-${randomUUID()}`, operation, status: 'generating', nodeId: input.nodeId, baseRevisionId: input.baseRevisionId
    } };
    this.runs.set(run.state.runId, run); this.requests.set(key, run.state.runId);
    this.launch(run, () => this.generate(run));
    return structuredClone(run.state);
  }
  async wait(id: string) { const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found'); await run.pending; return this.get(id); }
  get(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    return structuredClone(run.state);
  }
  cancel(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    // Once application is dispatched its outcome can be unknown. Never call it cancelled.
    if (run.state.status === 'generating') {
      run.abort.abort(); run.state.status = 'cancelled'; run.state.message = 'Cancelled before application';
    }
    return structuredClone(run.state);
  }
  private launch(run: Run, work: () => Promise<void>) {
    run.pending = work().catch(error => {
      if (run.abort.signal.aborted && run.state.status !== 'applying') { run.state.status = 'cancelled'; return; }
      const message = error instanceof Error ? error.message : String(error);
      run.state.status = run.state.status === 'applying' && /CANVAS_TIMEOUT|CANVAS_UNAVAILABLE|PERSISTENCE_PENDING/.test(message)
        ? 'awaiting-acknowledgement' : message.includes('VERSION_CONFLICT') ? 'conflict' : 'failed';
      run.state.error = message;
    }).finally(() => { run.pending = undefined; });
  }
  private install(run: Run) { return run.state.operation !== 'edit-diagram' ? this.place(run) : this.apply(run); }
  private async generate(run: Run) {
    const { input, abort } = run, operation = run.state.operation;
    const snapshot = await this.canvas.snapshot(input.sessionId, [...(input.baseRevisionId && input.baseRevisionId !== 'canvas' ? [input.baseRevisionId] : []), ...(input.references ?? []).map(ref => ref.revisionId)]);
    abort.signal.throwIfAborted();
    if (snapshot.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: read the canvas again');
    const box = input.nodeId.startsWith('grid:') && findBox(snapshot.document.scene.root, input.nodeId.slice(5));
    const unanchored = operation === 'create-diagram' && input.nodeId === 'canvas';
    if (!unanchored && (!box || box.kind !== 'diagram')) throw Error('Expected diagram GridBox');
    let base = box && box.kind === 'diagram' ? snapshot.document.scene.contents[box.contentId]
      : createStoredDiagram({ id: `context-${randomUUID()}`, revision: 0, ascii: '[New diagram]' }).diagram;
    if (!unanchored && base.revisionId !== input.baseRevisionId) throw Error('VERSION_CONFLICT: diagram base is no longer current');
    if (!run.submission && !run.agentContext && operation === 'edit-diagram') {
      const bound = snapshot.document.diagramContexts?.[base.diagramId];
      if (bound && bound.sourceFingerprint === diagramContextSourceFingerprint(base))
        run.agentContext = await loadDiagramAgentContext(bound, this.diagramContexts);
    }
    // Import only the exact target/reference revisions, including their logical node identities.
    for (const revision of snapshot.revisions ?? []) importDiagramRevision(revision);
    // Compatibility for in-process adapters that still supply a history record.
    if (!snapshot.revisions && snapshot.history) new CanvasHistory(snapshot.document, snapshot.canvas, snapshot.history, 'current');
    const existing = input.variant?.variantId ? snapshot.document.revisionReviews?.[input.variant.variantId] : undefined;
    if (input.variant?.variantId && !existing) throw Error('Variant not found');
    if (existing) {
      if (existing.diagramId !== base.diagramId) throw Error('Variant belongs to another diagram');
      const retained = await this.canvas.snapshot(input.sessionId, reviewRevisionIds(existing));
      for (const revision of retained.revisions ?? []) importDiagramRevision(revision);
      if (retained.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: canvas changed');
      base = getDiagramRevision(existing.headRevisionId).diagram;
    }
    const template = resolvePromptTemplate(input.template ?? defaultTemplateSelection(operation), operation);
    const references = this.resolveReferences(input.references ?? [], snapshot.history);
    const lines = base.content.ascii.split('\n');
    const editRanges = operation === 'edit-diagram'
      ? existing ? (() => {
        if (input.subtree || input.subtrees) throw Error('Refinement uses the saved variant scope; omit subtree targets');
