const id = z.string().min(1).max(200).refine(value => !['__proto__', 'constructor', 'prototype'].includes(value));
export const canvasViewSchema = z.object({
  id, name: z.string().trim().min(1).max(120), createdAt: z.string().datetime(),
  startCheckpointId: id, checkpointIds: z.array(id).min(1).max(100000),
  finalCheckpointId: id.optional(), savedAt: z.string().datetime().optional(),
  parentViewId: id.optional(), forkCheckpointId: id.optional(), alternativeGroupId: id.optional(),
  cameraViews: z.array(canvasCameraViewSchema).max(100).optional(), defaultCameraViewId: id.optional(),
  archivedAt: z.string().datetime().optional(), generation: canvasGenerationSchema.optional()
}).strict();
export type CanvasView = z.infer<typeof canvasViewSchema>;
export interface CanvasViews {
  saved: Record<string, CanvasView>; recording?: CanvasView;
  activeViewId?: string; workingCopies?: Record<string, string>;
}
export interface CanvasViewState extends CanvasViews { dirty?: boolean }
export interface CanvasViewSnapshot {
  checkpointId: string;
  document: import('./canvasHistory').ResolvedCanvasDocument;
  view: unknown;
  revisions: Record<string, import('./diagramRevision').DiagramRevision>;
}
export interface CanvasViewComparison { view: CanvasView; baseline: CanvasViewSnapshot; proposed: CanvasViewSnapshot }
export const canvasViewCommandSchema = z.object({
  operation: z.enum(['create', 'open', 'fork', 'save', 'alternatives', 'keep', 'discard', 'start', 'stop', 'list', 'read', 'apply', 'delete', 'cancel', 'promote-diffs']),
  name: z.string().trim().min(1).max(120).optional(), viewId: id.optional(),
  names: z.array(z.string().trim().min(1).max(120)).min(1).max(10)
    .refine(names => new Set(names).size === names.length, 'Alternative names must be unique').optional()
}).strict();
export type CanvasViewCommand = z.infer<typeof canvasViewCommandSchema>;

export function validateCanvasViews(views: CanvasViews | undefined, snapshots: Record<string, StoredCanvasSnapshot>) {
  if (!views) return;
  const value = z.object({ saved: z.record(id, canvasViewSchema), recording: canvasViewSchema.optional(),
    activeViewId: id.optional(), workingCopies: z.record(id, id).optional() }).strict().parse(views);
  if (value.activeViewId && (!value.saved[value.activeViewId] || value.saved[value.activeViewId].archivedAt)) throw Error('Invalid active CanvasView');
  for (const [viewId, checkpointId] of Object.entries(value.workingCopies ?? {})) {
    if (!value.saved[viewId] || !Object.hasOwn(snapshots, checkpointId)) throw Error('Invalid CanvasView working copy');
  }
  for (const [key, view] of Object.entries(value.saved)) {
    if (key !== view.id || !view.savedAt || !view.finalCheckpointId) throw Error('Invalid saved CanvasView');
    if (view.forkCheckpointId && !Object.hasOwn(snapshots, view.forkCheckpointId)) throw Error('Missing CanvasView fork checkpoint');
    const visited = new Set([key]);
    let parentId = view.parentViewId;
    while (parentId) {
      if (visited.has(parentId) || !value.saved[parentId]) throw Error('Invalid CanvasView ancestry');
      visited.add(parentId); parentId = value.saved[parentId].parentViewId;
    }
  }
  if (value.recording && (value.recording.savedAt || value.recording.finalCheckpointId || value.saved[value.recording.id])) throw Error('Invalid CanvasView recording');
  for (const view of [...Object.values(value.saved), ...(value.recording ? [value.recording] : [])]) {
    if (view.startCheckpointId !== view.checkpointIds[0] || view.finalCheckpointId && view.finalCheckpointId !== view.checkpointIds.at(-1)
      || view.checkpointIds.some(id => !Object.hasOwn(snapshots, id))) throw Error('Missing CanvasView checkpoint');
  }
}

export const canvasViewInstructions = 'Manage saved views of the active canvas. create with name saves the current canvas immediately. save appends a saved checkpoint to the active view (optional viewId must match). open with viewId switches to that view and resumes its working copy; unsaved edits are retained when switching and the camera stays in place. fork with viewId and name creates and opens a child from the parent saved checkpoint. alternatives with viewId and names (1–10 unique names) creates a group of children from ONE pinned saved checkpoint without switching the canvas. For LLM generation use the gen-alternatives AgentChat tool instead: it manages isolated parallel children with prompts and status. The alternatives operation here only makes empty copies. Each child is independent. Do not reuse diagram revision IDs or anchors across opens. keep with viewId saves that candidate and archives its group siblings and their descendants; only do this when the user chooses a candidate. discard archives a view and descendants. list/read return saved views, parentViewId, forkCheckpointId, alternativeGroupId, archivedAt, activeViewId and working copies; exclude archivedAt entries when presenting available views. History is represented by parent/child ancestry; saved checkpoints remain immutable. Legacy recording operations: start with name, stop to save, cancel to keep edits but discard recording metadata. Legacy apply restores a saved endpoint, delete removes a leaf, promote-diffs adds diagram diff alternatives. Stop recording before other mutations. Mutations require Workspace access, current expectedVersion when using MCP, and a unique requestId. Retry identical arguments after uncertain outcomes.';
import { deepFreeze } from '../immutability';
import { validateDiagram, type DiagramInput } from './diagram';
import { DiagramRevisionEditor, type DiagramRevision, type DiagramEdit, type PreparedDiagramEdit } from './diagramRevisionEditor';
import { diagramContentNodes } from './diagramContentNodes';
import type { SubtreeRange } from './diagramSubtreeEdit';
export type { DiagramRevision, DiagramEdit, DiagramRevisionId } from './diagramRevisionEditor';
export interface DiagramRevisionResult extends PreparedDiagramEdit { readonly revision: DiagramRevision; replacementRanges?: SubtreeRange[] }
export type DiagramRevisionSummary = Readonly<Pick<DiagramRevision, 'id' | 'diagramId' | 'parentId'>>;

// Domain operations return immutable revisions. Persistence/publication is explicit.
export function createDiagram(input: DiagramInput): DiagramRevisionResult {
  const prepared = new DiagramRevisionEditor({}, () => ({})).prepareCreate(input);
  return issueDiagramRevision(prepared);
}
export function reviseDiagram(base: DiagramRevision, edit: DiagramEdit): DiagramRevisionResult {
  const prepared = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }))
    .prepareEdit('edit', base.diagram.id, edit);
  if (prepared.diagram === base.diagram) return { ...prepared, revision: base };
  return issueDiagramRevision({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base);
}
export function deriveDiagram(base: DiagramRevision, input: Omit<DiagramInput, 'id' | 'revision'>, refs: Record<string, number>, sources: readonly DiagramRevision[]) {
  const allowed = new Set<string>();
  for (const source of sources) {
    if (source.diagramId !== base.diagramId) throw Error('Identity source belongs to another diagram');
    Object.values(source.nodeRefs).forEach(ref => allowed.add(ref));
  }
  const editor = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }));
  const prepared = editor.prepareEdit('derive', base.diagram.id, { kind: 'replace', input,
    nodeCorrespondence: Object.fromEntries(Object.entries(refs).filter(([ref]) => Object.values(base.nodeRefs).includes(ref))) });
  const nodes = diagramContentNodes(prepared.diagram.content), identities = new Map<string, string>();
  for (const [ref, line] of Object.entries(refs)) {
    const matching = nodes.filter(node => node.line === line);
    if (!allowed.has(ref) || matching.length !== 1 || identities.has(matching[0].id)) throw Error('Invalid derived node identity');
    identities.set(matching[0].id, ref);
  }
  return issueDiagramRevision({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base, identities);
}
function issueDiagramRevision(prepared: PreparedDiagramEdit, base?: DiagramRevision, identities = new Map<string, string>()): DiagramRevisionResult {
  const reverse = new Map([...prepared.nodeIds].map(([old, next]) => [next, old]));
  const record = deepFreeze({ id: prepared.diagram.revisionId, diagramId: prepared.diagram.diagramId,
    ...(base ? { parentId: base.id } : {}), diagram: prepared.diagram,
    nodeRefs: Object.fromEntries(diagramContentNodes(prepared.diagram.content).map(node => {
      const old = reverse.get(node.id);
      return [node.id, identities.get(node.id) || old && base?.nodeRefs[old] || `node-${crypto.randomUUID()}`];
    })) });
  validateDiagram(record.diagram);
  return { ...prepared, diagram: record.diagram, revision: record };
}

import type { CanvasHistoryService } from '../../../../domain/core/diagrams/canvasHistoryService';
import { createStore, type StoreApi } from 'zustand/vanilla';

import { MappingDocumentController, type ControllerSnapshot } from '../../../../domain/mapping/workspace/mappingDocumentController';
import type { MappingGridDocument } from '../../../../domain/mapping/workspace/mappingGrid';
import type { MappingCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { CanvasHistoryRecord } from '../../../../domain/core/diagrams/canvasHistory';
import { stateKey } from '../../../../domain/core/diagrams/canvasHistory';
import { CanvasCursorCopy } from '../canvas/cursorCopy';

/** Consumers can select and subscribe; mutations stay behind session commands. */
export function readable<T>(store: StoreApi<T>): Pick<StoreApi<T>, 'getState' | 'getInitialState' | 'subscribe'> {
  return { getState: store.getState, getInitialState: store.getInitialState, subscribe: store.subscribe };
}

export interface SavedDocumentState { name: string; savedName: string; savedScene: string; savedEdges?: string }
export interface DocumentStatus { isDirty: boolean; sceneDirty: boolean; canUndo: boolean; canRedo: boolean }

/** Stores publish committed semantic checkpoints from the command facade. A mounted
 * tldraw Editor owns live geometry and undo navigation; pointer/camera samples do
 * not publish application state. Headless sessions use the same domain commands. */
export class CanvasSession {
  readonly cursorCopy = new CanvasCursorCopy();
  readonly controller: MappingDocumentController;
  readonly document;
  private readonly documentState;
  readonly presentation;
  private readonly presentationState;
  readonly selection;
  private readonly selectionState;
  readonly controls;
  private readonly controlsState;
  readonly geometry;
  private readonly geometryState;
  readonly status;
  private readonly statusState;
  private baseline: SavedDocumentState;
  private savedSceneKey: string;
  private savedEdgesKey: string;
  private scene: MappingGridDocument['scene'];
  private edges: MappingGridDocument['edges'];
  private sceneKey: string;
  private edgesKey: string;
  private unsubscribe: () => void;
  private commitListeners = new Set<() => void>();

  constructor(input: SavedDocumentState & { document: MappingGridDocument; canvas: MappingCanvasState; history?: CanvasHistoryRecord }, history?: CanvasHistoryService) {
    this.baseline = { name: input.name, savedName: input.savedName, savedScene: input.savedScene, savedEdges: input.savedEdges };
    // Native anchors are renderer-local. Headless registry reads use estimated
    // layout until a legacy renderer explicitly supplies measured endpoints.
    this.controller = new MappingDocumentController(input.document, input.canvas, 0, undefined, undefined, input.history, history);
    const snapshot = this.controller.getSnapshot();
    this.scene = snapshot.document.scene; this.edges = snapshot.document.edges;
    this.sceneKey = stateKey(this.scene); this.edgesKey = stateKey(this.edges);
    this.savedSceneKey = stateKey(JSON.parse(input.savedScene)); this.savedEdgesKey = stateKey(JSON.parse(input.savedEdges ?? '[]'));
    this.documentState = createStore(() => ({ document: snapshot.document }));
    this.presentationState = createStore(() => ({ display: snapshot.canvas.display, diagramViews: snapshot.canvas.diagramViews }));
    this.selectionState = createStore(() => snapshot.canvas.selection);
    this.controlsState = createStore(() => snapshot.canvas.controls);
    this.geometryState = createStore(() => this.geometryOf(snapshot));
    this.statusState = createStore(() => this.statusOf(snapshot));
    this.document = readable(this.documentState);
    this.presentation = readable(this.presentationState);
    this.selection = readable(this.selectionState);
    this.controls = readable(this.controlsState);
    this.geometry = readable(this.geometryState);
    this.status = readable(this.statusState);
    let previous = snapshot;
    this.unsubscribe = this.controller.subscribe(() => {
      const next = this.controller.getSnapshot();
      if (next.document.scene !== this.scene) { this.scene = next.document.scene; this.sceneKey = stateKey(this.scene); }
      if (next.document.edges !== this.edges) { this.edges = next.document.edges; this.edgesKey = stateKey(this.edges); }
      // Publish all controller changes synchronously; React observes one completed transaction.
      if (next.canvas.display !== previous.canvas.display || next.canvas.diagramViews !== previous.canvas.diagramViews)
        this.presentationState.setState({ display: next.canvas.display, diagramViews: next.canvas.diagramViews });
      if (next.canvas.selection !== previous.canvas.selection) this.selectionState.setState(next.canvas.selection, true);
      if (next.canvas.controls !== previous.canvas.controls) this.controlsState.setState(next.canvas.controls, true);
      if (next.endpointBounds !== previous.endpointBounds || next.cell !== previous.cell || next.version !== previous.version)
        this.geometryState.setState(this.geometryOf(next));
      this.publishStatus(next);
      if (next.document !== previous.document) this.documentState.setState({ document: next.document });
      const committed = next.canvasRevisionId !== previous.canvasRevisionId;
      previous = next;
      if (committed) this.commitListeners.forEach(listener => listener());
    });
  }
  private geometryOf(s: ControllerSnapshot) { return { endpointBounds: s.endpointBounds, cell: s.cell, version: s.version }; }
  private statusOf(s: ControllerSnapshot): DocumentStatus {
    const sceneDirty = this.sceneKey !== this.savedSceneKey;
    return { sceneDirty, isDirty: sceneDirty || this.edgesKey !== this.savedEdgesKey || this.baseline.name !== this.baseline.savedName,
      canUndo: s.canUndo, canRedo: s.canRedo };
  }
  private publishStatus(s = this.controller.getSnapshot()) {
    const next = this.statusOf(s), prior = this.status.getState();
    if (Object.keys(next).some(key => next[key as keyof DocumentStatus] !== prior[key as keyof DocumentStatus])) this.statusState.setState(next);
  }
  /** A save acknowledgement names the captured baseline, not whatever is current now. */
  updateBaseline(input: SavedDocumentState) {
    if (input.savedScene !== this.baseline.savedScene) this.savedSceneKey = stateKey(JSON.parse(input.savedScene));
    if (input.savedEdges !== this.baseline.savedEdges) this.savedEdgesKey = stateKey(JSON.parse(input.savedEdges ?? '[]'));
    this.baseline = { name: input.name, savedName: input.savedName, savedScene: input.savedScene, savedEdges: input.savedEdges };
    this.publishStatus();
  }
  onCommit(listener: () => void) { this.commitListeners.add(listener); return () => { this.commitListeners.delete(listener); }; }
  dispose() { this.cursorCopy.clear(); this.unsubscribe(); this.commitListeners.clear(); }
}

